{
  "query": "서울과 도쿄 날씨 비교해 줘.",
  "tools": [
    {
      "name": "get_weather",
      "description": "지정한 도시의 현재 날씨를 반환한다.",
      "parameters": {
        "city": {
          "type": "string",
          "description": "도시 이름"
        }
      }
    }
  ],
  "output_format": {
    "tool_calls": [
      {
        "name": "string",
        "arguments": {
          "key": "value"
        }
      }
    ]
  }
}

{
  "query": "지난 달 서버 장애 로그를 수집해서 원인별로 분류하고, 각 원인에 대한 대응 방안을 Notion에 문서화한 뒤 인프라 팀에 슬랙으로 공유해 줘.",
  "tools": [
    {
      "name": "list_files",
      "description": "디렉토리 내 파일 목록을 반환한다.",
      "parameters": {
        "directory": {
          "type": "string",
          "description": "디렉토리 경로"
        },
        "pattern": {
          "type": "string",
          "description": "파일명 필터 패턴"
        },
        "modified_after": {
          "type": "string",
          "description": "이 날짜 이후 수정된 파일만 조회 (YYYY-MM-DD)"
        }
      }
    },
    {
      "name": "read_file",
      "description": "파일 내용을 읽어온다.",
      "parameters": {
        "path": {
          "type": "string",
          "description": "파일 경로"
        },
        "encoding": {
          "type": "string",
          "description": "파일 인코딩",
          "default": "utf-8"
        }
      }
    },
    {
      "name": "analyze_errors",
      "description": "로그 텍스트에서 에러 유형별 발생 건수를 분석한다.",
      "parameters": {
        "text": {
          "type": "string",
          "description": "분석할 로그 텍스트"
        },
        "group_by": {
          "type": "string",
          "description": "그룹화 기준 (예: error_type, severity, module)",
          "enum": [
            "error_type",
            "severity",
            "module"
          ]
        }
      }
    },
    {
      "name": "create_notion_page",
      "description": "Notion에 새 페이지를 생성한다.",
      "parameters": {
        "parent": {
          "type": "string",
          "description": "부모 페이지 또는 데이터베이스 ID"
        },
        "title": {
          "type": "string",
          "description": "페이지 제목"
        },
        "content": {
          "type": "string",
          "description": "페이지 내용"
        },
        "tags": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "태그 목록"
        }
      }
    },
    {
      "name": "send_slack_message",
      "description": "슬랙 채널에 메시지를 보낸다.",
      "parameters": {
        "channel": {
          "type": "string",
          "description": "채널명"
        },
        "message": {
          "type": "string",
          "description": "메시지 내용"
        },
        "priority": {
          "type": "string",
          "description": "알림 우선순위",
          "enum": [
            "normal",
            "urgent"
          ]
        }
      }
    }
  ],
  "output_format": {
    "tool_calls": [
      {
        "name": "string",
        "arguments": {
          "key": "value"
        }
      }
    ]
  }
}
